        .DELAY_ULINK_N18__0(`BD_SZ_UUT_ULINK_N18__0),
        .DELAY_ULINK_N18__0_UACK(`BD_SZ_UUT_ULINK_N18__0_UACK),
        .DELAY_ULINK_N18__1(`BD_SZ_UUT_ULINK_N18__1),
        .DELAY_ULINK_N18__1_UACK(`BD_SZ_UUT_ULINK_N18__1_UACK),
        .DELAY_ULINK_N18__1_SDELAY(`BD_SZ_UUT_ULINK_N18__1_SDELAY),
        .DELAY_ULINK_N18__2(`BD_SZ_UUT_ULINK_N18__2),
        .DELAY_ULINK_N18__2_UACK(`BD_SZ_UUT_ULINK_N18__2_UACK),
        .DELAY_ULINK_N18__2_SDELAY(`BD_SZ_UUT_ULINK_N18__2_SDELAY),
        .DELAY_ULINK_N18__3(`BD_SZ_UUT_ULINK_N18__3),
        .DELAY_ULINK_N18__3_UACK(`BD_SZ_UUT_ULINK_N18__3_UACK),
        .DELAY_ULINK_N27__1(`BD_SZ_UUT_ULINK_N27__1),
        .DELAY_ULINK_N27__1_UACK(`BD_SZ_UUT_ULINK_N27__1_UACK),
        .DELAY_ULINK_N27__2(`BD_SZ_UUT_ULINK_N27__2),
